<script setup>
import { reactive,ref } from 'vue';import { useRouter } from 'vue-router';import { ElMessage } from 'element-plus';import http from '../api/http'
const router=useRouter(),loading=ref(false),form=reactive({title:'',category:'校园活动',description:'',location:'',taskTime:'',applicationDeadline:'',rewardPoints:20,minCreditScore:60}),categories=['校园活动','课程辅导','生活服务','物品代取','创意设计','其他'];async function submit(){loading.value=true;try{const data=await http.post('/api/tasks',form);ElMessage.success('任务已发布，奖励积分已冻结');router.replace(`/tasks/${data.id}`)}catch(e){ElMessage.error(e.message)}finally{loading.value=false}}
</script>
<template><div style="max-width:780px;margin:auto"><div class="page-head"><div><h1>发布微任务</h1><p>把任务说清楚，让合适的同学更快找到你</p></div></div><section class="surface panel"><el-form label-position="top"><el-form-item label="任务标题"><el-input v-model="form.title" maxlength="100" show-word-limit placeholder="例如：帮忙拍摄社团招新照片"/></el-form-item><el-form-item label="任务分类"><el-select v-model="form.category" class="full"><el-option v-for="c in categories" :key="c" :value="c"/></el-select></el-form-item><el-form-item label="详细描述"><el-input v-model="form.description" type="textarea" :rows="5" maxlength="1000" show-word-limit/></el-form-item><el-form-item label="地点"><el-input v-model="form.location" placeholder="线上任务可填写“线上”"/></el-form-item><div style="display:grid;grid-template-columns:1fr 1fr;gap:16px" class="date-grid"><el-form-item label="申请截止"><el-date-picker v-model="form.applicationDeadline" class="full" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss"/></el-form-item><el-form-item label="任务时间"><el-date-picker v-model="form.taskTime" class="full" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss"/></el-form-item></div><div style="display:grid;grid-template-columns:1fr 1fr;gap:16px"><el-form-item label="奖励积分"><el-input-number v-model="form.rewardPoints" :min="1" :max="1000" class="full"/></el-form-item><el-form-item label="最低信用分"><el-input-number v-model="form.minCreditScore" :min="0" :max="100" class="full"/></el-form-item></div><el-alert :closable="false" type="info" title="发布后奖励积分将进入冻结状态；任务完成后结算给接取者。"/><div style="display:flex;justify-content:flex-end;gap:10px;margin-top:22px"><el-button @click="router.back()">取消</el-button><el-button type="primary" :loading="loading" @click="submit">确认发布</el-button></div></el-form></section></div></template><style scoped>@media(max-width:575px){.date-grid{grid-template-columns:1fr!important}}</style>
